616	def _normalize_set_value(field_name, value):
617	    """校验 set 操作的值并返回最终入库值；非法时抛 BatchUpdateError。
618	
619	    去除前后空白；仅含空白按清空（None）处理；来源/地区/行业保留内部空白与换行；
620	    重要日期非空时须为 YYYY-MM-DD 真实日历日期。
621	    """
622	    if not isinstance(value, str):
623	        raise BatchUpdateError("%s的设置值不是文本" % FIELD_LABELS[field_name])
624	    text = value.strip()
625	    if not text:
626	        return None
627	    if field_name == "important_date":
628	        ok, reason = check_date(text)
629	        if not ok:
630	            raise BatchUpdateError(reason)
631	    return text
