634	def batch_update_clients(database, payload):
635	    """执行批量修改，返回 {"updated_count": 去重后的客户数}；非法请求抛 BatchUpdateError。
636	
637	    任一问题都整次拒绝，不写入任何客户。
638	    """
639	    if not isinstance(payload, dict):
640	        raise BatchUpdateError("请求体必须是 JSON 对象")
641	
642	    raw_ids = payload.get("ids")
643	    if not isinstance(raw_ids, list):
644	        raise BatchUpdateError("ids 必须是客户编号数组")
645	    if not raw_ids:
646	        raise BatchUpdateError("未选择客户：请先勾选至少一名客户")
647	
648	    ids = []
649	    seen_ids = set()
650	    for raw_id in raw_ids:
651	        if isinstance(raw_id, bool) or not isinstance(raw_id, int) or raw_id <= 0:
652	            raise BatchUpdateError("客户编号必须是正整数：%r 不合法" % (raw_id,))
653	        if raw_id not in seen_ids:
654	            seen_ids.add(raw_id)
655	            ids.append(raw_id)
656	
657	    raw_updates = payload.get("updates", {})
658	    if not isinstance(raw_updates, dict):
659	        raise BatchUpdateError("updates 必须是字段修改说明对象")
660	    extra = [key for key in raw_updates if key not in OPTIONAL_FIELDS]
661	    if extra:
662	        raise BatchUpdateError("包含不能修改或不存在的字段：%s" % "、".join(extra))
663	
664	    actions = {}
665	    for field_name in OPTIONAL_FIELDS:
666	        spec = raw_updates.get(field_name, {"op": "keep"})
667	        if not isinstance(spec, dict):
668	            raise BatchUpdateError("%s的修改说明必须是对象" % FIELD_LABELS[field_name])
669	        op = spec.get("op")
670	        if op not in ("keep", "set", "clear"):
671	            raise BatchUpdateError(
672	                "%s的操作必须是 keep、set 或 clear 之一" % FIELD_LABELS[field_name])
673	        if op == "keep":
674	            continue
675	        if op == "clear":
676	            actions[field_name] = None
677	        else:
678	            actions[field_name] = _normalize_set_value(field_name, spec.get("value"))
679	
680	    if not actions:
681	        raise BatchUpdateError("全部字段均保持原值：请至少选择一个字段进行设置或清空")
682	
683	    placeholders = ",".join("?" for _ in ids)
684	    existing = {
685	        row[0]
686	        for row in database.execute(
687	            "SELECT id FROM clients WHERE id IN (%s)" % placeholders, ids
688	        )
689	    }
690	    missing = [cid for cid in ids if cid not in existing]
691	    if missing:
692	        raise BatchUpdateError("找不到对应客户，编号：%s" % "、".join(str(c) for c in missing))
693	
694	    assignments = ", ".join("%s = ?" % field_name for field_name in actions)
695	    params = list(actions.values()) + ids
696	    try:
697	        database.execute(
698	            "UPDATE clients SET %s WHERE id IN (%s)" % (assignments, placeholders), params
699	        )
700	        database.commit()
701	    except sqlite3.DatabaseError:
702	        database.rollback()
703	        raise BatchUpdateError("保存失败：数据库错误，本次修改未生效")
704	
705	    return {"updated_count": len(ids)}
