708	def parse_csv(text):
709	    """解析 RFC 4180 风格 CSV，返回 (header, data_rows)。
710	
711	    支持引号包裹的字段、引号内逗号与换行、双引号转义；
712	    引号外支持 LF / CRLF / CR 换行。结构损坏时抛 FileError：
713	    - 未加引号的字段中出现双引号（双引号只能在字段开头用于包住整个字段）；
714	    - 结束引号后出现逗号、换行或文件结束以外的字符（含空格）；
715	    - 文件结束时仍有字段处于引号内（引号未闭合）。
716	    错误信息区分上述三种情况，并指出发生在表头还是第 N 条数据记录
717	    （数据记录编号不包含表头，引号字段内的换行不增加编号）。
718	    """
719	    rows = []
720	    record = []
721	    field = []
722	    quoted = False        # 当前字段处于引号内
723	    started = False       # 当前字段已经开始（已有内容或已进入引号）
724	    closed = False       # 引号字段刚结束，等待逗号 / 换行 / 文件结束
725	    record_number = 0     # 0 = 表头，1 起为数据记录
726	    i = 0
727	    n = len(text)
728	
729	    def location():
730	        return "表头" if record_number == 0 else "第 %d 条数据记录" % record_number
731	
732	    def structure_error(kind):
733	        raise FileError("CSV 结构损坏（%s）：%s" % (location(), kind))
734	
735	    def finish_record():
736	        nonlocal record, field, started, closed
737	        record.append("".join(field))
738	        rows.append(record)
739	        record = []
740	        field = []
741	        started = False
742	        closed = False
743	
744	    while i < n:
745	        c = text[i]
746	        if quoted:
747	            if c == '"':
748	                if i + 1 < n and text[i + 1] == '"':
749	                    field.append('"')
750	                    i += 2
751	                    continue
752	                quoted = False
753	                closed = True
754	                i += 1
755	                continue
756	            if c == "\r":
757	                # 统一字段内换行符为 LF
758	                if i + 1 < n and text[i + 1] == "\n":
759	                    i += 1
760	                field.append("\n")
761	                i += 1
762	                continue
763	            field.append(c)
764	            i += 1
765	            continue
766	        if closed:
767	            # 引号已结束，只允许逗号、记录换行或文件结束
768	            if c == ",":
769	                record.append("".join(field))
770	                field = []
771	                started = False
772	                closed = False
773	            elif c in "\r\n":
774	                if c == "\r" and i + 1 < n and text[i + 1] == "\n":
775	                    i += 1
776	                finish_record()
777	                record_number += 1
778	            else:
779	                structure_error("结束引号后有多余字符，结束引号后只能紧接逗号、记录换行或文件结束")
780	            i += 1
781	            continue
782	        if c == '"' and not started:
783	            quoted = True
784	            started = True
785	        elif c == '"':
786	            structure_error("未加引号的字段中出现双引号，双引号只能在字段开头用于包住整个字段")
787	        elif c == ",":
788	            record.append("".join(field))
789	            field = []
790	            started = False
791	        elif c in "\r\n":
792	            if c == "\r" and i + 1 < n and text[i + 1] == "\n":
793	                i += 1
794	            if not started and not record and not field:
795	                # 空白行：不作为数据记录（显式的 "" 空字段 started=True，仍会保留）
796	                i += 1
797	                continue
798	            finish_record()
799	            record_number += 1
800	        else:
801	            field.append(c)
802	            started = True
803	        i += 1
804	    if quoted:
805	        structure_error("引号未闭合，文件结束时仍有字段处于引号内")
806	    if started or field or record or closed:
807	        record.append("".join(field))
808	        rows.append(record)
809	    if not rows:
810	        raise FileError("CSV 内容为空：缺少表头")
811	    return rows[0], rows[1:]
