814	def check_date(value):
815	    """校验 YYYY-MM-DD 且为真实日历日期，返回 (是否合法, 错误原因)。"""
816	    match = DATE_RE.match(value)
817	    if not match:
818	        return False, "重要日期格式无效（%s）：须为 YYYY-MM-DD" % value
819	    try:
820	        datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
821	    except ValueError:
822	        return False, "重要日期无效（%s）：不是真实日历日期" % value
823	    return True, None
