861	                "reason": "列数不符：表头有 %d 列，该记录有 %d 列" % (len(headers), len(raw)),
862	            })
863	            continue
864	
865	        name = raw[name_index].strip()
866	        problems = []
867	        if not name:
868	            problems.append("缺少名称：name 列为空")
869	        date_value = ""
