266	// 等待被挂起的保存请求出现（页面已发出请求、服务尚未给出结果）
267	async function waitForHeld(session, timeout = 5000) {
268	  const deadline = Date.now() + timeout;
269	  while (Date.now() < deadline) {
270	    if (session.held.length > 0) return session.held[0];
271	    await new Promise(r => setTimeout(r, 25));
272	  }
273	  throw new Error("保存请求未在限定时间内发出");
274	}
