305	function listWarnBanner(snap) {
306	  return snap.banners.some(b => b.cls.includes("warn") &&
307	    b.text.includes("读取客户列表失败") &&
308	    b.text.includes("列表暂未更新") &&
309	    b.text.includes("可能仍是保存前") &&
310	    /稍后.*(刷新|重新打开)|重新打开.*刷新/.test(b.text) &&
311	    b.text.includes("无需再次保存"));
312	}
