314	function cleanedUp(snap) {
315	  return snap.selCount === "0" &&
316	    snap.selNoneHint && snap.selChips.length === 0 &&
317	    !snap.checkAllChecked && !snap.checkAllIndeterminate &&
318	    snap.rows.every(r => !r.checked && !r.selected) &&
319	    snap.fields.every(f => f.op === "keep" && f.value === "" && f.disabled) &&
320	    snap.submitText === "保存修改" && snap.submitDisabled;
321	}
