323	// 「结果无法确认」横幅：bad 类；明确无法确认、提醒先核对客户列表再决定是否重新保存；
324	// 不出现成功数量；不做「全部拒绝/资料保持原样」的肯定结论；不自动重发。
325	// （文案可以、也应当明确否定「未修改/已回滚」，故不把这些词本身列为违禁。）
326	function unconfirmedBanner(snap) {
327	  return snap.banners.length === 1 && snap.banners[0].cls.includes("bad") &&
328	    snap.banners[0].text.includes("无法确认") &&
329	    snap.banners[0].text.includes("核对客户列表") &&
330	    /重新保存/.test(snap.banners[0].text) &&
331	    snap.banners[0].text.includes("不会自动重新提交") &&
332	    !/已成功处理/.test(snap.reportText) &&
333	    !/全部拒绝/.test(snap.reportText) &&
334	    !/保持原样/.test(snap.reportText);
335	}
