337	// 无法确认时不做保存成功后的清理：勾选、字段操作与已填内容原样保留
338	function retainedState(snap, {count, ops}) {
339	  return snap.selCount === String(count) &&
340	    snap.rows.filter(r => r.checked).length === count &&
341	    ops.every(([key, op, value]) => {
342	      const f = snap.fields.find(x => x.key === key);
343	      return f && f.op === op && (value === undefined || f.value === value);
344	    }) &&
345	    snap.submitText === "保存修改" && !snap.submitDisabled;
346	}
