    const byIdL = async id =>
      (await listClients(lBase)).clients.find(x => x.id === id);

    const session = await openSession(browser, lBase);
    const {page, counts} = session;

    // -----------------------------------------------------------------
    // L1：set 填过文字/无效日期后改 keep——以最后选择的 keep 为准
