      bL42.id === l2 && bL42.name === "回归乙" &&
      bL42.source === "来 源\tA" &&
      bL42.industry === "行 业\n第二行\t保留" &&
      bL43.id === l3 && bL43.name === "回归丙" &&
      bL43.source === "丙网" && bL43.region === "丙地区" &&
      bL43.industry === null && bL43.important_date === "2022-05-05",
